import{_ as r,l as i,o as e,c as L,v as l,p as s,x as o,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"LL 与 FIRST/FOLLOW","description":"","frontmatter":{"title":"LL 与 FIRST/FOLLOW","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ll-first-follow.md","filePath":"cs/ll-first-follow.md","lastUpdated":1789023840000}'),p={name:"cs/ll-first-follow.md"};function F(h,a,O,f,T,_){const t=i("Mermaid");return e(),L("div",null,[a[1]||(a[1]=l('<h1 id="ll-与-first-follow" tabindex="-1">LL 与 FIRST/FOLLOW <a class="header-anchor" href="#ll-与-first-follow" aria-label="Permalink to &quot;LL 与 FIRST/FOLLOW&quot;">​</a></h1><div class="epigraph"><p>FIRST 回答「这条产生式能以哪些记号开头」；FOLLOW 回答「这个非终结符后面能跟什么」。二者填满预测表。</p><footer>—— 据龙书第 4 章整理</footer></div><p>上一课<a href="/cs/recursive-descent">递归下降</a>已经用手写预测。本课不重写每个 <code>parseA</code>。缺口是：把预测做成<strong>表</strong>，并给出何时一个记号恰好对应一条产生式——LL(1)。FIRST/FOLLOW 是填表算法，不是另一套语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写下降在分支多时易漏冲突。LL(1)：对每个 \\(A\\) 与前瞻记号 \\(a\\)，至多一条产生式。FIRST(\\(\\alpha)\\)：\\(\\alpha\\) 能推出的开头终结符；若 \\(\\alpha\\Rightarrow^*\\varepsilon\\)，再看 FOLLOW(\\(A\\))。冲突：同一格两条产生式，或 FIRST 相交。缺口是计算这两个集合，而不是再定义 CFG。</p><p>左递归与公共前缀常导致非 LL(1)。提取与改写仍要，本课把冲突显示在表上。</p><h3 id="follow-不是-first-的别名" tabindex="-1">FOLLOW 不是 FIRST 的别名 <a class="header-anchor" href="#follow-不是-first-的别名" aria-label="Permalink to &quot;FOLLOW 不是 FIRST 的别名&quot;">​</a></h3><p>FIRST 看右部能长出什么头。FOLLOW 看 \\(A\\) 在哪些产生式里出现在中间，后面兄弟的 FIRST，以及父亲的 FOLLOW。\\(\\varepsilon\\) 产生式全靠 FOLLOW 填表。搞混则可选结构全错。</p><p><span class="marginnote">龙书 4.4 节给 FIRST/FOLLOW 的不动点迭代。LL(\\(k\\)) 用 \\(k\\) 个记号，本课 \\(k=1\\)。表驱动分析栈代替递归调用栈，与下降等价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>迭代求 FIRST：终结符、\\(\\varepsilon\\)、再传播。FOLLOW：从开始符号的 <code>$</code> 起，按产生式传播。填 \\(M[A,a]\\)。分析：栈底 <code>$</code>、顶 \\(S\\)，与输入比；终结符匹配弹出，非终结符查表展开。</p>',11)),(e(),s(c,null,{default:o(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22CFG%22%5D%20--%3E%20FF%5B%22FIRST%20%2F%20FOLLOW%22%5D%0A%20%20FF%20--%3E%20TAB%5B%22LL(1)%20%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20STK%5B%22%E6%A0%88%E5%BC%8F%E9%A2%84%E6%B5%8B%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>若表有冲突，语言不是 LL(1)，改文法或换 LR。开始符号的结束符 <code>$</code> 必须进 FOLLOW，否则文件末尾无法接受。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归下降是 LL(1) 表的递归写法；表驱动是显式栈。错误：查表空则非法。同步记号可用 FOLLOW 当恢复点，本课点名。表达式用 LL 常要左因子与优先级分层，文法变丑——这是后课 LR 的动机之一。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不移进归约，不造项集。不算 LL(2)。不处理二义文法的优先级声明（那是 Yacc/LR 的习惯）。后课默认：LL(1) = FIRST/FOLLOW 无冲突的预测表。更强的自底向上分析是 LR。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FIRST 管产生式开头；FOLLOW 管可空之后。</li><li>LL(1) 表每格至多一条；冲突则非 LL(1)。</li><li>表驱动与递归下降同一预测。</li><li>冲突就改文法或改用 LR，不要靠回溯。</li><li>出处：Aho et al., 龙书第 4 章。</li></ul>',7))])}const u=r(p,[["render",F]]);export{m as __pageData,u as default};
